## Clases ES6

Las clases de ES6 son **azúcar sintáctica** sobre la herencia prototípica que estudiaste en el módulo anterior. No cambian el modelo de prototipos — lo hacen más legible.

```javascript
// Lo que escribes con clases:
class Persona {
  constructor(nombre, edad) {
    this.nombre = nombre;
    this.edad = edad;
  }

  saludar() {
    return `Hola, soy ${this.nombre}`;
  }
}

// Lo que JavaScript hace internamente (equivalente):
function Persona(nombre, edad) {
  this.nombre = nombre;
  this.edad = edad;
}
Persona.prototype.saludar = function () {
  return `Hola, soy ${this.nombre}`;
};
```

Ambos son idénticos a nivel de prototipos.

---

## El constructor

El método `constructor` se ejecuta automáticamente con `new`. Solo puede haber uno por clase:

```javascript
class Producto {
  constructor(nombre, precio, stock) {
    this.nombre = nombre;
    this.precio = precio;
    this.stock = stock;
  }
}

const libro = new Producto('JavaScript Pro', 45000, 10);
console.log(libro.nombre); // 'JavaScript Pro'
console.log(libro.precio); // 45000
```

---

## Métodos de instancia

Los métodos definidos dentro de la clase van automáticamente al prototipo:

```javascript
class Contador {
  constructor(inicio = 0) {
    this.valor = inicio;
  }

  incrementar() {
    this.valor++;
    return this;
  }

  decrementar() {
    this.valor--;
    return this;
  }

  resetear() {
    this.valor = 0;
    return this;
  }

  obtener() {
    return this.valor;
  }
}

const c = new Contador(10);
// Retornar 'this' permite encadenamiento de métodos
c.incrementar().incrementar().decrementar();
console.log(c.obtener()); // 11
```

---

## Diferencias clave vs funciones constructoras

```javascript
// 1. Las clases NO se elevan (hoisting)
new Persona('Ana'); // ❌ ReferenceError
class Persona { constructor(n) { this.nombre = n; } }

// Las funciones constructoras SÍ se elevan:
new Persona2('Ana'); // ✅ Funciona
function Persona2(n) { this.nombre = n; }

// 2. Las clases siempre están en strict mode
class Demo {
  metodo() {
    // Automáticamente 'use strict'
  }
}

// 3. Solo se pueden llamar con 'new'
class Punto {
  constructor(x, y) { this.x = x; this.y = y; }
}
Punto(1, 2); // ❌ TypeError: Class constructor Punto cannot be invoked without 'new'
```

---

## Retornar `this` para encadenamiento

Un patrón muy útil llamado **method chaining** o **fluent interface**:

```javascript
class QueryBuilder {
  constructor() {
    this.tabla = '';
    this.condiciones = [];
    this.limite = null;
  }

  from(tabla) {
    this.tabla = tabla;
    return this;
  }

  where(condicion) {
    this.condiciones.push(condicion);
    return this;
  }

  limit(n) {
    this.limite = n;
    return this;
  }

  build() {
    let q = `SELECT * FROM ${this.tabla}`;
    if (this.condiciones.length > 0)
      q += ` WHERE ${this.condiciones.join(' AND ')}`;
    if (this.limite) q += ` LIMIT ${this.limite}`;
    return q;
  }
}

const query = new QueryBuilder()
  .from('usuarios')
  .where('edad > 18')
  .where('activo = true')
  .limit(10)
  .build();

console.log(query);
// 'SELECT * FROM usuarios WHERE edad > 18 AND activo = true LIMIT 10'
```

