class Temperatura {
  constructor(celsius) {
    this.celsius = celsius;
  }

  aFahrenheit() {
    return this.celsius * 9 / 5 + 32;
  }

  aKelvin() {
    return this.celsius + 273.15;
  }

  toString() {
    return `${this.celsius}°C`;
  }
}

const t = new Temperatura(100);
console.log(t.aFahrenheit()); // 212
console.log(t.aKelvin());     // 373.15
console.log(String(t));       // '100°C' (llama toString())

class Pila {
  constructor() {
    this._items = [];
  }

  push(item) {
    this._items.push(item);
    return this;
  }

  pop() {
    return this._items.pop();
  }

  peek() {
    return this._items[this._items.length - 1];
  }

  get size() {
    return this._items.length;
  }

  isEmpty() {
    return this._items.length === 0;
  }
}

const pila = new Pila();
pila.push(1).push(2).push(3);
console.log(pila.peek()); // 3
console.log(pila.size);   // 3
console.log(pila.pop());  // 3
console.log(pila.size);   // 2

